//! Pseudo component construction comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_pseudo_components.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const QUANTITIES: [&str; 4] = ["volume", "enthalpy", "entropy", "compressibility"];
const ATOL: [f64; 4] = [1e-12, 1e-6, 1e-9, 1e-12];
const RTOL: f64 = 1e-10;

fn list(fields: &[&str], index: usize) -> Vec<f64> {
    fields[index]
        .split(',')
        .map(|value| value.parse().unwrap())
        .collect()
}

#[test]
fn pseudo_components_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/pseudo_components.csv")
        .lines()
        .skip(1)
    {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let kind = match fields[1] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = fields[2].split(',').collect();
        let critical_temperatures = list(&fields, 3);
        let critical_pressures = list(&fields, 4);
        let acentric_factors = list(&fields, 5);
        let molar_masses = list(&fields, 6);
        let temperature: f64 = fields[7].parse().unwrap();
        let pressure: f64 = fields[8].parse().unwrap();
        let composition = list(&fields, 9);
        let phase = match fields[10].parse::<i32>().unwrap() {
            2 => thermopack_rs::Phase::Vapor,
            _ => thermopack_rs::Phase::Liquid,
        };
        let model = Cubic::new_pseudo(
            kind,
            &components,
            &critical_temperatures,
            &critical_pressures,
            &acentric_factors,
            Some(&molar_masses),
        )
        .unwrap();
        let state = model.prepare(temperature, &composition).unwrap();
        let volume = state.volume(pressure, phase).unwrap();
        let enthalpy = state.enthalpy(volume).unwrap();
        let entropy = state.entropy(volume).unwrap();
        let computed = state.pressure(volume).unwrap().value;
        let compressibility = computed * volume / (thermopack_rs::R * temperature);
        let actual = [volume, enthalpy, entropy, compressibility];
        let expected: Vec<f64> = fields[11..].iter().map(|v| v.parse().unwrap()).collect();
        assert_eq!(expected.len(), actual.len(), "{case}");
        for (position, (source, native)) in expected.iter().zip(actual.iter()).enumerate() {
            let tolerance = ATOL[position] + RTOL * source.abs();
            assert!(
                (source - native).abs() <= tolerance,
                "{case} {}: source {source} native {native}",
                QUANTITIES[position]
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 30);
}

#[test]
fn the_pseudo_component_keeps_its_critical_point() {
    // The critical temperature and the critical pressure of the pseudo
    // component are the requested ones, so the acentric factor of the classic
    // alpha correlation is the requested one as well.
    let model = Cubic::new_pseudo(
        CubicKind::PengRobinson,
        &["PSEUDO"],
        &[350.0],
        &[4.0e6],
        &[0.3],
        Some(&[0.05]),
    )
    .unwrap();
    let critical = model.pseudo_critical(&[1.0]).unwrap();
    assert!((critical.temperature - 350.0).abs() < 1.0);
    assert!((critical.pressure - 4.0e6).abs() < 1.0e5);
}

#[test]
fn the_pseudo_lists_must_match_the_components() {
    let error = Cubic::new_pseudo(
        CubicKind::PengRobinson,
        &["PSEUDO", "PSEUDO"],
        &[350.0],
        &[4.0e6],
        &[0.3],
        None,
    )
    .unwrap_err();
    assert!(matches!(error, thermopack_rs::Error::InvalidInput(_)));
}
